CREATE FUNCTION public.mc_v7_report(p_from date,p_to date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE r text; starttext text; endtext text; orders jsonb; entries jsonb; products jsonb; debts jsonb; totals jsonb;
BEGIN
 r:=private.mc_v7_role();IF r NOT IN ('owner','cashier','viewer') THEN RAISE EXCEPTION 'CLOUD_ROLE_DENIED'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_from>p_to OR p_from<'2000-01-01' OR p_to>'2100-12-31' THEN RAISE EXCEPTION 'CLOUD_DATE_INVALID'; END IF;
 starttext:=to_char(p_from::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh' AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS');endtext:=to_char((p_to+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh' AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS');
 SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t."soldAt" DESC),'[]') INTO orders FROM (
 SELECT c.order_id id,c.created_at "soldAt",COALESCE(ct.recipient_name,'') "recipientName",COALESCE(ct.phone,'') phone,(SELECT count(*) FROM public.sales_units u WHERE u.order_id=c.order_id) quantity,c.subtotal::text subtotal,c.discount::text discount,c.total::text "goodsTotal",COALESCE(ct.shipping_fee,0)::text shipping,(c.total+COALESCE(ct.shipping_fee,0))::text "payableTotal",
 (SELECT COALESCE(sum((snapshot::jsonb->>'unit_cost')::numeric),0)::text FROM public.sales_units WHERE order_id=c.order_id) "knownCost",
 (SELECT count(*) FROM public.sales_units WHERE order_id=c.order_id AND (snapshot::jsonb->>'unit_cost') IS NULL) "unknownCosts",
 CASE WHEN EXISTS(SELECT 1 FROM public.sales_units WHERE order_id=c.order_id AND (snapshot::jsonb->>'unit_cost') IS NULL) THEN NULL ELSE (c.total-(SELECT COALESCE(sum((snapshot::jsonb->>'unit_cost')::numeric),0) FROM public.sales_units WHERE order_id=c.order_id))::text END "grossMargin",
 private.mc_v7_finance(c.order_id)->>'credit' "creditToDate",private.mc_v7_finance(c.order_id)->>'adjustedTotal' "adjustedToDate",private.mc_v7_finance(c.order_id)->>'due' "dueNow",private.mc_v7_finance(c.order_id)->>'refundDue' "refundDueNow"
 FROM public.sales_confirmations c LEFT JOIN public.order_contacts ct ON ct.order_id=c.order_id WHERE c.created_at>=starttext AND c.created_at<endtext) t;
 SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t."createdAt" DESC),'[]') INTO entries FROM (
 SELECT e.id,e.order_id "orderId",e.kind,e.method,e.amount::text amount,e.note,e.created_at "createdAt",COALESCE(ct.recipient_name,'') "recipientName" FROM public.finance_entries e LEFT JOIN public.order_contacts ct ON ct.order_id=e.order_id WHERE e.created_at>=starttext AND e.created_at<endtext) t;
 SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.quantity DESC),'[]') INTO products FROM (
 SELECT u.snapshot::jsonb->>'product_name' name,u.snapshot::jsonb->>'product_code' code,u.snapshot::jsonb->>'size' size,count(*) quantity,sum((u.snapshot::jsonb->>'unit_price')::numeric)::text "grossSales" FROM public.sales_units u JOIN public.sales_confirmations c ON c.order_id=u.order_id WHERE c.created_at>=starttext AND c.created_at<endtext GROUP BY u.snapshot::jsonb->>'product_name',u.snapshot::jsonb->>'product_code',u.snapshot::jsonb->>'size') t;
 SELECT COALESCE(jsonb_agg(t.f),'[]') INTO debts FROM (SELECT private.mc_v7_finance(id) f FROM public.sales_orders WHERE status<>'CANCELLED_DRAFT') t WHERE (t.f->>'due')::numeric>0 OR (t.f->>'refundDue')::numeric>0;
 SELECT jsonb_build_object('orders',jsonb_array_length(orders),'quantity',COALESCE(sum((v->>'quantity')::numeric),0),'subtotal',COALESCE(sum((v->>'subtotal')::numeric),0)::text,'discount',COALESCE(sum((v->>'discount')::numeric),0)::text,'goodsTotal',COALESCE(sum((v->>'goodsTotal')::numeric),0)::text,'shipping',COALESCE(sum((v->>'shipping')::numeric),0)::text,'payableTotal',COALESCE(sum((v->>'payableTotal')::numeric),0)::text,'knownCost',COALESCE(sum((v->>'knownCost')::numeric),0)::text,'unknownCosts',COALESCE(sum((v->>'unknownCosts')::numeric),0),'grossMargin',CASE WHEN COALESCE(sum((v->>'unknownCosts')::numeric),0)>0 THEN NULL ELSE COALESCE(sum((v->>'grossMargin')::numeric),0)::text END) INTO totals FROM jsonb_array_elements(orders) v;
 SELECT totals||jsonb_build_object('receipts',COALESCE(sum((v->>'amount')::numeric) FILTER(WHERE v->>'kind'='RECEIPT'),0)::text,'refunds',COALESCE(sum((v->>'amount')::numeric) FILTER(WHERE v->>'kind'='REFUND'),0)::text,'credits',COALESCE(sum((v->>'amount')::numeric) FILTER(WHERE v->>'kind'='CREDIT'),0)::text,'netCash',(COALESCE(sum((v->>'amount')::numeric) FILTER(WHERE v->>'kind'='RECEIPT'),0)-COALESCE(sum((v->>'amount')::numeric) FILTER(WHERE v->>'kind'='REFUND'),0))::text) INTO totals FROM jsonb_array_elements(entries) v;
 SELECT totals||jsonb_build_object('dueNow',COALESCE(sum((v->>'due')::numeric),0)::text,'refundDueNow',COALESCE(sum((v->>'refundDue')::numeric),0)::text,'debtOrders',jsonb_array_length(debts)) INTO totals FROM jsonb_array_elements(debts) v;
 RETURN jsonb_build_object('range',jsonb_build_object('from',p_from,'to',p_to,'timezone','Asia/Ho_Chi_Minh'),'generatedAt',now(),'totals',totals,'orders',orders,'entries',entries,'products',products,'debts',debts);
END $$;
REVOKE ALL ON FUNCTION public.mc_v7_report(date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mc_v7_report(date,date) TO authenticated;
